// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 회원가입 (14번)" (0ec54a7d7fc44cdeb062f6c1399a8d6d).
// #189: docs/ui-guide.md 공통 값(uiStyles, ConfirmModal, FieldError)으로 바꿨다.
import { useState, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage, getFieldErrors } from "../api/client";
import {
  INPUT_PATTERNS,
  INPUT_RULES,
  checkAvailable,
  formatPhoneInput,
  signup,
  toPhoneDigits,
  type DuplicateField,
} from "../api/member";
import "./Signup.css";
import AuthHeader from "../components/AuthHeader";
import AuthShowcase from "../components/AuthShowcase";
import ConfirmModal from "../components/ConfirmModal";
import FieldError from "../components/FieldError";
import Footer from "../components/Footer";
import { HEADER_BUTTON_CLASS, HEADER_BUTTON_COLOR } from "../components/headerStyles";
import { buttonClass, CARD, INPUT, NOTICE, PAGE_BACKGROUND } from "../components/uiStyles";

const PATTERNS = INPUT_PATTERNS;
const RULE_TEXT = INPUT_RULES;

const DUPLICATE_CODES: Record<string, DuplicateField> = {
  DUPLICATE_LOGIN_ID: "loginId",
  DUPLICATE_PHONE: "phone",
  DUPLICATE_NICKNAME: "nickname",
};

type Field = DuplicateField | "password" | "passwordConfirm";

function toRequestValue(field: Field, value: string) {
  return field === "phone" ? toPhoneDigits(value) : value;
}

// 중복 확인 결과. value가 지금 입력값과 다르면(확인 후 수정) 다시 확인해야 한다 (REQ-SIGNUP-003~005).
interface CheckResult {
  value: string;
  available: boolean;
}

const SMALL_ICON = "material-symbols-outlined text-[15px] leading-none";

// 입력칸 아래 안내(info)·확인(ok) 문구. 오류는 공통 FieldError를 쓴다.
function Hint({ tone, children }: { tone: "info" | "ok"; children: ReactNode }) {
  return (
    <p className={`${INPUT.hint} flex items-center gap-1 ${tone === "ok" ? "font-bold text-devin-ink" : ""}`}>
      <span className={SMALL_ICON} aria-hidden="true">
        {tone === "ok" ? "check_circle" : "info"}
      </span>
      {children}
    </p>
  );
}

function RequiredLabel({ htmlFor, children }: { htmlFor: string; children: ReactNode }) {
  return (
    <label className={INPUT.label} htmlFor={htmlFor}>
      {children} <span className="text-devin-red">*</span>
    </label>
  );
}

export default function Signup() {
  const navigate = useNavigate();
  const [values, setValues] = useState<Record<Field, string>>({
    loginId: "",
    password: "",
    passwordConfirm: "",
    nickname: "",
    phone: "",
  });
  const [checks, setChecks] = useState<Partial<Record<DuplicateField, CheckResult>>>({});
  const [checking, setChecking] = useState<DuplicateField | null>(null);
  // 서버가 알려준 필드별 에러. 그 필드를 다시 고치면 지운다.
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<Field, string>>>({});
  const [formError, setFormError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);

  const formatValid = (field: DuplicateField | "password") =>
    PATTERNS[field].test(toRequestValue(field, values[field]));
  const confirmed = (field: DuplicateField) => {
    const check = checks[field];
    return check?.available === true && check.value === toRequestValue(field, values[field]);
  };
  const passwordsMatch = values.password === values.passwordConfirm;
  const canSubmit =
    formatValid("password") &&
    passwordsMatch &&
    confirmed("loginId") &&
    confirmed("nickname") &&
    confirmed("phone") &&
    !submitting;

  function change(field: Field, value: string) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setFieldErrors((prev) => ({ ...prev, [field]: undefined }));
    setFormError(null);
  }

  async function check(field: DuplicateField) {
    const value = toRequestValue(field, values[field]);
    setChecking(field);
    try {
      const available = await checkAvailable(field, value);
      setChecks((prev) => ({ ...prev, [field]: { value, available } }));
    } catch (err) {
      setFieldErrors((prev) => ({ ...prev, [field]: getErrorMessage(err) }));
    } finally {
      setChecking(null);
    }
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    setFormError(null);
    try {
      await signup({
        loginId: values.loginId,
        password: values.password,
        nickname: values.nickname,
        phone: toRequestValue("phone", values.phone),
      });
      setCompleted(true);
    } catch (err) {
      // 중복 확인 뒤 다른 사람이 먼저 가입한 경우: 그 칸을 "이미 사용 중"으로 바꾼다.
      const duplicated = DUPLICATE_CODES[getErrorCode(err) ?? ""];
      const errors = getFieldErrors(err);
      if (duplicated) {
        const value = toRequestValue(duplicated, values[duplicated]);
        setChecks((prev) => ({ ...prev, [duplicated]: { value, available: false } }));
      } else if (errors.length > 0) {
        setFieldErrors(Object.fromEntries(errors.map(({ field, reason }) => [field, reason])));
      } else {
        setFormError(getErrorMessage(err));
      }
    } finally {
      setSubmitting(false);
    }
  }

  // 아이디·닉네임·전화번호 칸의 오류 문구: 형식 오류 → 서버 오류 → 이미 사용 중 순서. 없으면 null
  function duplicateError(field: DuplicateField) {
    const check = checks[field];
    if (values[field] === "") return null;
    if (!formatValid(field)) return RULE_TEXT[field];
    if (fieldErrors[field]) return fieldErrors[field];
    if (check && check.value === toRequestValue(field, values[field]) && !check.available) return "이미 사용 중이에요.";
    return null;
  }

  // 오류가 없을 때의 안내: 규칙 → 사용할 수 있음 → 중복 확인 요청
  function duplicateHint(field: DuplicateField) {
    const error = duplicateError(field);
    if (error) return <FieldError message={error} />;
    if (values[field] === "") return <Hint tone="info">{RULE_TEXT[field]}</Hint>;
    if (confirmed(field)) return <Hint tone="ok">사용할 수 있어요.</Hint>;
    return <Hint tone="info">중복 확인을 눌러 주세요.</Hint>;
  }

  function inputClass(invalid: boolean) {
    return `${INPUT.base} ${invalid ? INPUT.error : ""}`;
  }

  function checkButton(field: DuplicateField) {
    const disabled = !formatValid(field) || checking !== null || confirmed(field);
    return (
      <button
        className={`${buttonClass("secondary")} shrink-0`}
        disabled={disabled}
        onClick={() => check(field)}
        type="button"
      >
        {checking === field ? "확인 중..." : "중복 확인"}
      </button>
    );
  }

  const passwordError =
    fieldErrors.password ?? (values.password !== "" && !formatValid("password") ? RULE_TEXT.password : undefined);
  const passwordConfirmInvalid = values.passwordConfirm !== "" && !passwordsMatch;

  return (
    <div id="page-signup">
      {/* 회원가입 완료 (REQ-SIGNUP-006): 닫으면 로그인 화면으로 간다 */}
      {completed && (
        <ConfirmModal
          message="Dev in_ 회원이 된 걸 환영해요. 로그인하고 다른 개발자들과 질문과 답변을 나눠 보세요."
          title="회원가입을 마쳤어요"
          onCancel={() => navigate("/login", { replace: true })}
        >
          <p className="text-devin-gray">닫으면 로그인 화면으로 이동해요.</p>
        </ConfirmModal>
      )}
      <div className={`${PAGE_BACKGROUND} min-h-screen flex flex-col text-devin-ink antialiased`}>
        <AuthHeader>
          <span className="hidden sm:inline text-xs font-medium text-devin-gray">이미 계정이 있나요?</span>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.white}`} to="/login">
            로그인
          </Link>
        </AuthHeader>

        <main className="flex-1 max-w-6xl mx-auto w-full px-4 sm:px-6 py-10 flex items-center justify-center">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 w-full items-stretch">
            {/* 왼쪽: 서비스 소개 */}
            <AuthShowcase className="lg:col-span-5" />

            {/* 오른쪽: 회원가입 폼. 한 줄로 쌓이는 좁은 화면에서는 폼을 먼저 보여 준다 */}
            <section className={`${CARD} order-first lg:order-none lg:col-span-7 p-4 sm:p-6`}>
              <h2 className="mb-6 text-lg font-extrabold text-devin-ink">회원가입</h2>

              <form className="space-y-5" noValidate onSubmit={handleSubmit}>
                <div>
                  <RequiredLabel htmlFor="user-nickname">닉네임</RequiredLabel>
                  <div className="flex gap-2">
                    <input
                      aria-invalid={duplicateError("nickname") !== null}
                      autoComplete="nickname"
                      className={inputClass(duplicateError("nickname") !== null)}
                      id="user-nickname"
                      maxLength={10}
                      name="nickname"
                      onChange={(e) => change("nickname", e.target.value)}
                      placeholder="닉네임 입력"
                      type="text"
                      value={values.nickname}
                    />
                    {checkButton("nickname")}
                  </div>
                  {duplicateHint("nickname")}
                </div>

                <div>
                  <RequiredLabel htmlFor="user-id">아이디</RequiredLabel>
                  <div className="flex gap-2">
                    <input
                      aria-invalid={duplicateError("loginId") !== null}
                      autoComplete="username"
                      className={inputClass(duplicateError("loginId") !== null)}
                      id="user-id"
                      maxLength={12}
                      name="loginId"
                      onChange={(e) => change("loginId", e.target.value)}
                      placeholder="영문·숫자 8~12자"
                      type="text"
                      value={values.loginId}
                    />
                    {checkButton("loginId")}
                  </div>
                  {duplicateHint("loginId")}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-4">
                  <div>
                    <RequiredLabel htmlFor="user-password">비밀번호</RequiredLabel>
                    <input
                      aria-invalid={passwordError !== undefined}
                      autoComplete="new-password"
                      className={inputClass(passwordError !== undefined)}
                      id="user-password"
                      maxLength={12}
                      name="password"
                      onChange={(e) => change("password", e.target.value)}
                      placeholder="••••••••"
                      type="password"
                      value={values.password}
                    />
                    {passwordError ? (
                      <FieldError message={passwordError} />
                    ) : (
                      <Hint tone="info">{RULE_TEXT.password}</Hint>
                    )}
                  </div>

                  <div>
                    <RequiredLabel htmlFor="user-password-confirm">비밀번호 확인</RequiredLabel>
                    <input
                      aria-invalid={passwordConfirmInvalid}
                      autoComplete="new-password"
                      className={inputClass(passwordConfirmInvalid)}
                      id="user-password-confirm"
                      maxLength={12}
                      name="passwordConfirm"
                      onChange={(e) => change("passwordConfirm", e.target.value)}
                      placeholder="••••••••"
                      type="password"
                      value={values.passwordConfirm}
                    />
                    {values.passwordConfirm !== "" &&
                      (passwordsMatch ? (
                        <Hint tone="ok">비밀번호가 일치해요.</Hint>
                      ) : (
                        <FieldError message="비밀번호가 일치하지 않아요." />
                      ))}
                  </div>
                </div>

                <div>
                  <RequiredLabel htmlFor="user-phone">휴대전화번호</RequiredLabel>
                  <div className="flex gap-2">
                    <input
                      aria-invalid={duplicateError("phone") !== null}
                      autoComplete="tel"
                      className={`${inputClass(duplicateError("phone") !== null)} font-mono tracking-wider`}
                      id="user-phone"
                      inputMode="numeric"
                      maxLength={13}
                      name="phone"
                      onChange={(e) => change("phone", formatPhoneInput(e.target.value))}
                      placeholder="010-0000-0000"
                      type="tel"
                      value={values.phone}
                    />
                    {checkButton("phone")}
                  </div>
                  {duplicateHint("phone")}
                  <Hint tone="info">아이디·비밀번호를 찾을 때 이 전화번호로 본인 확인을 해요.</Hint>
                </div>

                {formError && (
                  <p className={NOTICE.error} role="alert">
                    <span className="material-symbols-outlined text-[18px] leading-5" aria-hidden="true">
                      error
                    </span>
                    {formError}
                  </p>
                )}

                <button className={`${buttonClass("primary")} w-full`} disabled={!canSubmit} type="submit">
                  {submitting ? "가입 중..." : "회원가입 완료"}
                  <span className="material-symbols-outlined text-[18px] leading-none" aria-hidden="true">
                    arrow_forward
                  </span>
                </button>
              </form>
            </section>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}
